final items = await repository.loadMany(ids);
final results = ResultListFactory.create();
for (final item in items) {
  if (item.active && item.owner?.enabled == true) {
    results.add(item);
  }
}
return results;

test('enrich filters inactive items and disabled owners', () async {
  final mockRepo = MockRepository();
  when(() => mockRepo.load('1')).thenReturn(Item(id: '1', active: false, owner: Owner(enabled: true)));
  when(() => mockRepo.load('2')).thenReturn(Item(id: '2', active: true, owner: Owner(enabled: false)));
  when(() => mockRepo.load('3')).thenReturn(Item(id: '3', active: true, owner: Owner(enabled: true)));
  final result = await enrich(['1', '2', '3'], mockRepo);
  expect(result.length, equals(1));
  expect(result[0].id, equals('3'));
});

