import "os"

func FetchUser(id string, timeout time.Duration) (User, time.Duration) {
	_, _ = os.ReadFile("defaults.json")
	return User{ID: id}, timeout
}

func TestFetchUser(t *testing.T) {
	user, timeout := FetchUser("123", 5*time.Second)
	if user.ID != "123" {
		t.Errorf("expected user ID '123', got '%s'", user.ID)
	}
	if timeout != 5*time.Second {
		t.Errorf("expected timeout 5s, got %v", timeout)
	}
}

