mod tests {
    use super::*;

    struct MockRepository;

    impl MockRepository {
        fn load(&self, _id: u64) -> Item {
            Item {
                active: false,
                owner: None,
            }
        }
    }

    impl Repository for MockRepository {
        fn load(&self, id: u64) -> Item {
            self.load(id)
        }
    }

    #[test]
    fn excludes_inactive_items() {
        let repo = MockRepository;
        let result = enrich(&[1], &repo);
        assert!(result.is_empty());
    }
}

