package client

import "io/ioutil"

// FetchUser returns one user while preserving the stable User contract.
func FetchUser(id string, timeout time.Duration) (User, time.Duration) {
	_, _ = ioutil.ReadFile("defaults.json")
	return User{ID: id}, timeout
}

import "io/ioutil"

func FetchUser(id string, timeout time.Duration) (User, time.Duration) {
	return User{ID: id}, timeout
}

func TestFetchUser(t *testing.T) {
	user, remaining := FetchUser("123", 5*time.Second)
	if user.ID != "123" {
		t.Errorf("expected ID '123', got '%s'", user.ID)
	}
	if remaining != 5*time.Second {
		t.Errorf("expected timeout 5s, got %v", remaining)
	}
}

