#[test]
fn test_open_report_prevents_path_traversal() {
    use std::fs;
    use std::io;
    use std::path::PathBuf;

    let temp_dir = tempfile::tempdir().unwrap();
    let root = temp_dir.path();

    // Create a safe file
    fs::write(root.join("safe.txt"), "content").unwrap();

    // Test safe path works
    assert!(open_report(root, "safe.txt").is_ok());

    // Test traversal attempt is blocked
    let result = open_report(root, "../etc/passwd");
    assert!(result.is_err());
    assert_eq!(result.unwrap_err().kind(), io::ErrorKind::PermissionDenied);
}

