test('enrich filters items by active status and enabled owner', () async {
  final mockRepo = MockRepository();
  when(() => mockRepo.load('1')).thenReturn(Item(id: '1', active: true, owner: Owner(enabled: true)));
  when(() => mockRepo.load('2')).thenReturn(Item(id: '2', active: false, owner: Owner(enabled: true)));
  when(() => mockRepo.load('3')).thenReturn(Item(id: '3', active: true, owner: Owner(enabled: false)));
  when(() => mockRepo.load('4')).thenReturn(Item(id: '4', active: true, owner: null));
  final result = await enrich(['1', '2', '3', '4'], mockRepo);
  expect(result.length, equals(1));
  expect(result[0].id, equals('1'));
})

